func newInvoiceState() unsafe.Pointer { return unsafe.Pointer(new(factoringreadiness.InvoiceState)) }

func newNInvoiceState(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]factoringreadiness.InvoiceState, n)))
}

func ptrInvoiceState(p unsafe.Pointer, c int32) any {
	r := (*factoringreadiness.InvoiceState)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.InvoiceID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (**string)(unsafe.Pointer(&r.FactoringCompanyID))
	case 4:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Verdict))
	case 6:
		return &r.Checks
	case 7:
		return (*int64)(unsafe.Pointer(&r.FailedChecks))
	case 8:
		return &r.OpenBalanceMinor
	case 9:
		return &r.ReadySince
	case 10:
		return &r.ReadyAnnouncedAt
	case 11:
		return &r.EvaluatedAt
	case 12:
		return &r.CreatedAt
	}
	return nil
}

func valueInvoiceState(p unsafe.Pointer, c int32) any {
	r := (*factoringreadiness.InvoiceState)(p)
	switch c {
	case 0:
		return string(r.InvoiceID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		if r.FactoringCompanyID == nil {
			return nil
		}
		return string(*r.FactoringCompanyID)
	case 4:
		return string(r.CustomerID)
	case 5:
		return string(r.Verdict)
	case 6:
		if r.Checks == nil {
			return keel.EmptyJSONArray
		}
		return r.Checks
	case 7:
		return int64(r.FailedChecks)
	case 8:
		return r.OpenBalanceMinor
	case 9:
		if r.ReadySince == nil {
			return nil
		}
		return *r.ReadySince
	case 10:
		if r.ReadyAnnouncedAt == nil {
			return nil
		}
		return *r.ReadyAnnouncedAt
	case 11:
		return r.EvaluatedAt
	case 12:
		return r.CreatedAt
	}
	return nil
}

func attachInvoiceState(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*factoringreadiness.InvoiceState)(p)
	switch rel {
	case 0:
		r.Invoice = (*invoice.Invoice)(child)
	case 1:
		r.Customer = (*customer.Customer)(child)
	case 2:
		r.FactoringCompany = (*factoringcompany.FactoringCompany)(child)
	}
}

func init() {
	invoiceStatesTable.Relations[0].Target = invoicedb.InvoicesSchema()
	invoiceStatesTable.Relations[1].Target = customerdb.CustomersSchema()
	invoiceStatesTable.Relations[2].Target = factoringcompanydb.FactoringCompaniesSchema()
}

